package org.slavicmyths.kalin;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.world.level.block.*;import net.minecraft.world.level.block.state.BlockState;
/** Sparse 65x65 camp. Open center and four wide gates; never flattens terrain. */
public final class KalinCamp {
 public static Map<BlockPos,BlockState> blueprint(BlockPos c){var b=new LinkedHashMap<BlockPos,BlockState>();
 for(int n=-32;n<=32;n++)for(int y=0;y<3;y++){if(Math.abs(n)>4){b.put(c.offset(n,y,-32),Blocks.SPRUCE_FENCE.defaultBlockState());b.put(c.offset(n,y,32),Blocks.SPRUCE_FENCE.defaultBlockState());b.put(c.offset(-32,y,n),Blocks.SPRUCE_FENCE.defaultBlockState());b.put(c.offset(32,y,n),Blocks.SPRUCE_FENCE.defaultBlockState());}}
 tent(b,c,0,-20,8,6,6);for(int x:new int[]{-20,20})for(int z:new int[]{-17,16})tent(b,c,x,z,4,4,4);
 for(int x:new int[]{-27,27})for(int z:new int[]{-27,27}){for(int dx:new int[]{-2,2})for(int dz:new int[]{-2,2})for(int y=0;y<5;y++)b.put(c.offset(x+dx,y,z+dz),Blocks.SPRUCE_LOG.defaultBlockState());for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++)b.put(c.offset(x+dx,4,z+dz),Blocks.SPRUCE_PLANKS.defaultBlockState());for(int dx=-2;dx<=2;dx++)for(int dz=-2;dz<=2;dz++)if(Math.abs(dx)==2||Math.abs(dz)==2)b.put(c.offset(x+dx,5,z+dz),Blocks.SPRUCE_FENCE.defaultBlockState());}
 for(int x:new int[]{-12,12})for(int z:new int[]{-14,14}){b.put(c.offset(x,0,z),Blocks.STONE_BRICKS.defaultBlockState());b.put(c.offset(x,1,z),Blocks.CAMPFIRE.defaultBlockState());for(int y=0;y<4;y++)b.put(c.offset(x+3,y,z),Blocks.SPRUCE_FENCE.defaultBlockState());b.put(c.offset(x+3,4,z),Blocks.RED_WOOL.defaultBlockState());b.put(c.offset(x+3,3,z),Blocks.YELLOW_WOOL.defaultBlockState());b.put(c.offset(x+4,4,z),Blocks.RED_WOOL.defaultBlockState());b.put(c.offset(x-2,0,z),Blocks.SPRUCE_PLANKS.defaultBlockState());b.put(c.offset(x-2,1,z),Blocks.IRON_BARS.defaultBlockState());}
 for(int x:new int[]{-26,26})for(int z:new int[]{-8,8}){b.put(c.offset(x,0,z),Blocks.YELLOW_CARPET.defaultBlockState());b.put(c.offset(x+1,0,z),Blocks.RED_CARPET.defaultBlockState());}for(int x:new int[]{-8,8})b.put(c.offset(x,0,26),Blocks.YELLOW_CARPET.defaultBlockState());return b;}
 private static void tent(Map<BlockPos,BlockState>b,BlockPos c,int x,int z,int rx,int rz,int h){for(int dx=-rx;dx<=rx;dx++)for(int dz=-rz;dz<=rz;dz++){int top=Math.max(2,h-Math.abs(dx)/2);b.put(c.offset(x+dx,top,z+dz),(dx%4==0?Blocks.YELLOW_WOOL:Blocks.RED_WOOL).defaultBlockState());if((Math.abs(dx)==rx||Math.abs(dz)==rz)&&!(dz==rz&&Math.abs(dx)<=2))for(int y=0;y<top;y++)b.put(c.offset(x+dx,y,z+dz),Blocks.RED_WOOL.defaultBlockState());}for(int y=0;y<h+1;y++)b.put(c.offset(x,y,z),Blocks.SPRUCE_FENCE.defaultBlockState());}
 private KalinCamp(){}
}
